/**
 * Import path for controller data.
 *
 *   import { controllers, categories, vocabularies, yearExtent } from "../data/controllers";
 *   import type { Controller, CategorySlug } from "../data/controllers";
 *
 * `controllers.json` is generated by `node scripts/build-data.mjs` (`npm run data:build`).
 * Image URLs are filled by that script's folder scan. Do not read the image directory
 * from UI code, and do not hand-edit the JSON or the files under `public/images`.
 */
import catalog from "./controllers.json";
import type { Catalog } from "./types";

export type {
  Catalog,
  CatalogMeta,
  CategoryInfo,
  CategorySlug,
  Controller,
  LegacyController,
  Tag,
  Vocabularies,
  YearExtent,
  YearPrecision,
} from "./types";

/**
 * JSON imports widen string-literal unions (`CategorySlug`, `YearPrecision`) to `string`.
 * `Widen` checks that every catalog field is present and has the right primitive shape.
 * The exports below are then viewed as the strict catalog types.
 */
type Widen<T> = T extends string
  ? string
  : T extends number
    ? number
    : T extends boolean
      ? boolean
      : T extends null
        ? null
        : null extends T
          ? Widen<Exclude<T, null>> | null
          : T extends (infer U)[]
            ? Widen<U>[]
            : T extends object
              ? { [K in keyof T]: Widen<T[K]> }
              : T;

const checked: Widen<Catalog> = catalog;
const data = checked as Catalog;

export const meta = data.meta;
export const controllers = data.controllers;
export const categories = data.categories;
export const vocabularies = data.vocabularies;
export const yearExtent = data.yearExtent;
